  add("errors.runtimeFailed", "Cinematic Text stopped because the runtime reported an error.", "El texto cinematográfico se detuvo porque el sistema informó un error.", "Filmtext wurde beendet, weil die Laufzeit einen Fehler gemeldet hat.", "Çalışma zamanı hata bildirdiği için Sinematik Metin durduruldu.", "Le texte cinématographique s’est arrêté, car le moteur a signalé une erreur.", "توقف النص السينمائي لأن نظام التشغيل أبلغ عن خطأ.", "Văn bản điện ảnh đã dừng vì hệ thống chạy báo lỗi.", "Tekst filmowy zatrzymał się, ponieważ środowisko wykonawcze zgłosiło błąd.", "O texto cinematográfico foi interrompido porque o sistema reportou um erro.");
  add("errors.closeFailed", "Cinematic Text could not be closed safely.", "No se pudo cerrar el texto cinematográfico de forma segura.", "Filmtext konnte nicht sicher geschlossen werden.", "Sinematik Metin güvenli biçimde kapatılamadı.", "Le texte cinématographique n’a pas pu être fermé correctement.", "تعذر إغلاق النص السينمائي بأمان.", "Không thể đóng Văn bản điện ảnh an toàn.", "Nie udało się bezpiecznie zamknąć tekstu filmowego.", "Não foi possível fechar o texto cinematográfico com segurança.");
  add("errors.durationInvalid", "Enter a duration of at least 0.2 seconds.", "Ingresa una duración mínima de 0,2 segundos.", "Eine Dauer von mindestens 0,2 Sekunden eingeben.", "En az 0,2 saniyelik bir süre girin.", "Saisissez une durée d’au moins 0,2 seconde.", "أدخل مدة لا تقل عن 0.2 ثانية.", "Nhập thời lượng ít nhất 0,2 giây.", "Wprowadź czas co najmniej 0,2 sekundy.", "Informe uma duração de pelo menos 0,2 segundo.");
  add("errors.focusFailed", "Cinematic Text could not capture the authoring controls.", "El texto cinematográfico no pudo capturar los controles de edición.", "Filmtext konnte die Bearbeitungssteuerung nicht übernehmen.", "Sinematik Metin düzenleme kontrollerini devralamadı.", "Le texte cinématographique n’a pas pu prendre le contrôle des outils d’édition.", "تعذر على النص السينمائي التقاط عناصر تحكم التأليف.", "Văn bản điện ảnh không thể tiếp nhận điều khiển biên soạn.", "Tekst filmowy nie mógł przejąć sterowania edycją.", "O texto cinematográfico não conseguiu assumir os controles de edição.");
  add("errors.freecamFailed", "The Cinematic Text freecam could not start.", "No se pudo iniciar la cámara libre del texto cinematográfico.", "Die Filmtext-Freecam konnte nicht gestartet werden.", "Sinematik Metin serbest kamerası başlatılamadı.", "La caméra libre du texte cinématographique n’a pas pu démarrer.", "تعذر تشغيل الكاميرا الحرة للنص السينمائي.", "Không thể khởi động freecam của Văn bản điện ảnh.", "Nie udało się uruchomić swobodnej kamery tekstu filmowego.", "Não foi possível iniciar a câmera livre do texto cinematográfico.");
  add("errors.gizmoFailed", "The text gizmo could not be opened.", "No se pudo abrir el gizmo del texto.", "Das Text-Gizmo konnte nicht geöffnet werden.", "Metin gizmosu açılamadı.", "Le gizmo du texte n’a pas pu être ouvert.", "تعذر فتح أداة تحريك النص.", "Không thể mở gizmo văn bản.", "Nie udało się otworzyć gizma tekstu.", "Não foi possível abrir o gizmo do texto.");
  add("errors.liveUpdateFailed", "The live text update could not be applied.", "No se pudo aplicar la actualización del texto en vivo.", "Die Live-Aktualisierung des Textes konnte nicht angewendet werden.", "Canlı metin güncellemesi uygulanamadı.", "La mise à jour du texte en direct n’a pas pu être appliquée.", "تعذر تطبيق تحديث النص المباشر.", "Không thể áp dụng cập nhật văn bản trực tiếp.", "Nie udało się zastosować aktualizacji tekstu na żywo.", "Não foi possível aplicar a atualização do texto em tempo real.");
  add("errors.missingDefinition", "The text definition is missing.", "Falta la definición del texto.", "Die Textdefinition fehlt.", "Metin tanımı eksik.", "La définition du texte est manquante.", "تعريف النص مفقود.", "Thiếu định nghĩa văn bản.", "Brakuje definicji tekstu.", "A definição do texto está ausente.");
  add("errors.nameRequired", "Give this text a name.", "Dale un nombre a este texto.", "Diesem Text einen Namen geben.", "Bu metne bir ad verin.", "Donnez un nom à ce texte.", "امنح هذا النص اسمًا.", "Đặt tên cho văn bản này.", "Nadaj temu tekstowi nazwę.", "Dê um nome a este texto.");
  add("errors.previewFailed", "The text preview could not start.", "No se pudo iniciar la vista previa del texto.", "Die Textvorschau konnte nicht gestartet werden.", "Metin ön izlemesi başlatılamadı.", "L’aperçu du texte n’a pas pu démarrer.", "تعذر بدء معاينة النص.", "Không thể bắt đầu xem trước văn bản.", "Nie udało się uruchomić podglądu tekstu.", "Não foi possível iniciar a prévia do texto.");
  add("errors.releaseFocusFailed", "The authoring controls could not be released.", "No se pudieron liberar los controles de edición.", "Die Bearbeitungssteuerung konnte nicht freigegeben werden.", "Düzenleme kontrolleri bırakılamadı.", "Les contrôles d’édition n’ont pas pu être libérés.", "تعذر تحرير عناصر تحكم التأليف.", "Không thể giải phóng điều khiển biên soạn.", "Nie udało się zwolnić sterowania edycją.", "Não foi possível liberar os controles de edição.");
  add("errors.restoreSceneFailed", "The previous scene could not be restored.", "No se pudo restaurar la escena anterior.", "Die vorherige Szene konnte nicht wiederhergestellt werden.", "Önceki sahne geri yüklenemedi.", "La scène précédente n’a pas pu être restaurée.", "تعذرت استعادة المشهد السابق.", "Không thể khôi phục cảnh trước đó.", "Nie udało się przywrócić poprzedniej sceny.", "Não foi possível restaurar a cena anterior.");
  add("errors.saveFailed", "The text could not be saved.", "No se pudo guardar el texto.", "Der Text konnte nicht gespeichert werden.", "Metin kaydedilemedi.", "Le texte n’a pas pu être enregistré.", "تعذر حفظ النص.", "Không thể lưu văn bản.", "Nie udało się zapisać tekstu.", "Não foi possível salvar o texto.");
  add("errors.saveSceneFailed", "The text could not be saved to the Custom Scene.", "No se pudo guardar el texto en la escena personalizada.", "Der Text konnte nicht in der benutzerdefinierten Szene gespeichert werden.", "Metin Özel Sahneye kaydedilemedi.", "Le texte n’a pas pu être enregistré dans la scène personnalisée.", "تعذر حفظ النص في المشهد المخصص.", "Không thể lưu văn bản vào Cảnh tùy chỉnh.", "Nie udało się zapisać tekstu w scenie niestandardowej.", "Não foi possível salvar o texto na cena personalizada.");
  add("errors.saveTimelineFailed", "The text could not be saved to the Timeline.", "No se pudo guardar el texto en la línea de tiempo.", "Der Text konnte nicht in der Timeline gespeichert werden.", "Metin Zaman Çizelgesine kaydedilemedi.", "Le texte n’a pas pu être enregistré dans la timeline.", "تعذر حفظ النص في الخط الزمني.", "Không thể lưu văn bản vào Dòng thời gian.", "Nie udało się zapisać tekstu na osi czasu.", "Não foi possível salvar o texto na linha do tempo.");
  add("errors.scaleInvalid", "Set a text scale of at least 0.1.", "Establece una escala de texto mínima de 0,1.", "Eine Textskalierung von mindestens 0,1 einstellen.", "Metin ölçeğini en az 0,1 olarak ayarlayın.", "Définissez une échelle de texte d’au moins 0,1.", "اضبط مقياس النص على 0.1 على الأقل.", "Đặt tỷ lệ văn bản ít nhất là 0,1.", "Ustaw skalę tekstu na co najmniej 0,1.", "Defina uma escala de texto de pelo menos 0,1.");
  add("errors.sceneEntryChanged", "That Custom Scene entry changed. Reopen the text editor.", "Esa entrada de la escena personalizada cambió. Vuelve a abrir el editor de texto.", "Dieser Eintrag der benutzerdefinierten Szene wurde geändert. Den Texteditor erneut öffnen.", "Bu Özel Sahne girdisi değişti. Metin düzenleyiciyi yeniden açın.", "Cette entrée de scène personnalisée a changé. Rouvrez l’éditeur de texte.", "تغيّر عنصر المشهد المخصص هذا. أعد فتح محرر النص.", "Mục Cảnh tùy chỉnh đó đã thay đổi. Hãy mở lại trình chỉnh sửa văn bản.", "Ten wpis sceny niestandardowej uległ zmianie. Otwórz ponownie edytor tekstu.", "Essa entrada da cena personalizada mudou. Abra o editor de texto novamente.");
  add("errors.scenePrepareFailed", "The Custom Scene could not be prepared for text editing.", "No se pudo preparar la escena personalizada para editar el texto.", "Die benutzerdefinierte Szene konnte nicht für die Textbearbeitung vorbereitet werden.", "Özel Sahne metin düzenleme için hazırlanamadı.", "La scène personnalisée n’a pas pu être préparée pour la modification du texte.", "تعذر تجهيز المشهد المخصص لتحرير النص.", "Không thể chuẩn bị Cảnh tùy chỉnh để chỉnh sửa văn bản.", "Nie udało się przygotować sceny niestandardowej do edycji tekstu.", "Não foi possível preparar a cena personalizada para edição de texto.");
  add("errors.textRequired", "Write the text that should appear.", "Escribe el texto que debe aparecer.", "Den Text eingeben, der erscheinen soll.", "Görünecek metni yazın.", "Saisissez le texte à afficher.", "اكتب النص الذي يجب أن يظهر.", "Viết nội dung cần hiển thị.", "Wpisz tekst, który ma się pojawić.", "Escreva o texto que deve aparecer.");
  add("errors.timelinePrepareFailed", "The Timeline clip could not be prepared for text editing.", "No se pudo preparar el clip de la línea de tiempo para editar el texto.", "Der Timeline-Clip konnte nicht für die Textbearbeitung vorbereitet werden.", "Zaman Çizelgesi klibi metin düzenleme için hazırlanamadı.", "Le clip de la timeline n’a pas pu être préparé pour la modification du texte.", "تعذر تجهيز مقطع الخط الزمني لتحرير النص.", "Không thể chuẩn bị clip Dòng thời gian để chỉnh sửa văn bản.", "Nie udało się przygotować klipu osi czasu do edycji tekstu.", "Não foi possível preparar o clipe da linha do tempo para edição de texto.");
  add("errors.transitionsTooLong", "The in and out times cannot exceed the total duration.", "Los tiempos de entrada y salida no pueden superar la duración total.", "Ein- und Ausblendzeit dürfen die Gesamtdauer nicht überschreiten.", "Giriş ve çıkış süreleri toplam süreyi aşamaz.", "Les durées d’entrée et de sortie ne peuvent pas dépasser la durée totale.", "لا يمكن أن تتجاوز مدتا الدخول والخروج المدة الإجمالية.", "Thời gian vào và ra không được vượt quá tổng thời lượng.", "Czasy wejścia i wyjścia nie mogą przekraczać całkowitego czasu.", "Os tempos de entrada e saída não podem ultrapassar a duração total.");
  add("errors.waitForUpdate", "Wait for the current update to finish.", "Espera a que termine la actualización actual.", "Warten, bis die aktuelle Aktualisierung abgeschlossen ist.", "Geçerli güncellemenin bitmesini bekleyin.", "Attendez la fin de la mise à jour en cours.", "انتظر حتى يكتمل التحديث الحالي.", "Chờ bản cập nhật hiện tại hoàn tất.", "Poczekaj na zakończenie bieżącej aktualizacji.", "Aguarde a conclusão da atualização atual.");
