    // Camera Director.
    "(stay visible with H · hidden in playback)": "(permanece visible con H · se oculta durante la reproducción)",
    "Anchor gaze": "Anclar mirada",
    "Append an exact copy of the first keyframe to create a seamless closing segment": "Añadir una copia exacta del primer fotograma clave para crear un cierre continuo",
    "Attach aimed": "Adjuntar al objetivo",
    "Capture the current camera as a new keyframe (L)": "Capturar la cámara actual como un nuevo fotograma clave (L)",
    "Choose a recorded keyframe, move the camera, then press Replace to update only that pose": "Elige un fotograma clave grabado, mueve la cámara y pulsa Reemplazar para actualizar solo esa pose",
    "Cinematic camera controls": "Controles de cámara cinematográfica",
    "Degrees per second. Negative reverses the direction. Also flown live with A/D while orbiting.": "Grados por segundo. Un valor negativo invierte la dirección. También se ajusta en vivo con A/D durante la órbita.",
    "Distance to the target. Also flown live with W/S while orbiting.": "Distancia al objetivo. También se ajusta en vivo con W/S durante la órbita.",
    "Duplicate the selected keyframe (midpoint to the next one, or +2s at the end)": "Duplicar el fotograma clave seleccionado (a mitad del siguiente o +2 s al final)",
    "Ease In": "Entrada suave",
    "Ease In/Out": "Entrada/salida suave",
    "Ease Out": "Salida suave",
    "Exit": "Salir",
    "Filters the raw mouse movement, so a quick flick eases in and coasts out instead of snapping. Different from rotation smoothing, which eases the camera toward the angle the mouse already set.": "Filtra el movimiento directo del ratón para que un gesto rápido entre y salga con suavidad en vez de saltar. Es distinto del suavizado de rotación, que acerca la cámara al ángulo ya definido por el ratón.",
    "Flight speed. The low end is deliberately very slow for creeping dolly moves; hold Shift for turbo and Alt/Ctrl for precision.": "Velocidad de vuelo. El mínimo es deliberadamente lento para movimientos de dolly; mantén Shift para acelerar y Alt/Ctrl para precisión.",
    "Free look (N): the mouse rotates the camera without holding right-click. Active while the panel is hidden with H.": "Vista libre (N): el ratón rota la cámara sin mantener pulsado el botón derecho. Permanece activa al ocultar el panel con H.",
    "Guide intensity": "Intensidad de las guías",
    "Height above the target's origin. Also flown live with Q/E while orbiting.": "Altura sobre el origen del objetivo. También se ajusta en vivo con Q/E durante la órbita.",
    "How softly the camera rides the target. 0 locks it 1:1 to the subject's movement; higher values let it trail and settle, like an operator following rather than being bolted on.": "Define qué tan suavemente la cámara acompaña al objetivo. 0 la fija 1:1 a su movimiento; valores mayores permiten que se retrase y se estabilice como una cámara operada.",
    "Level": "Nivelar",
    "Momentum-based flight: input becomes thrust and the camera glides and banks into turns": "Vuelo basado en impulso: los controles aplican empuje y la cámara planea e inclina en los giros",
    "Natural: the curve's own pacing from keyframe times. Segment: constant speed between keyframes, times still exact. Continuous: even speed across the whole path — the most metered, but intermediate keyframe times become guides.": "Natural: usa el ritmo de la curva según los fotogramas clave. Segmento: velocidad constante entre fotogramas, conservando sus tiempos. Continuo: velocidad uniforme en toda la trayectoria; los tiempos intermedios pasan a ser guías.",
    "Orbit: circle the target automatically, starting from the distance and height you already framed. While it turns: W/S dolly, Q/E crane, A/D change rotation speed.": "Órbita: rodea automáticamente el objetivo desde la distancia y altura encuadradas. Durante el giro: W/S desplaza, Q/E eleva y A/D cambia la velocidad de rotación.",
    "Pin the camera at eye height above the ground for walking-height shots": "Fijar la cámara a la altura de los ojos para tomas a nivel de caminata",
    "Preserve the exact camera position and rotation relative to the attached entity. The composition stays fixed while you drive, turn, bank or change direction.": "Conservar la posición y rotación exactas respecto a la entidad adjunta. La composición permanece fija al conducir, girar, inclinarse o cambiar de dirección.",
    "Rack focus: keep the attached target sharp automatically as it moves": "Cambio de foco: mantener nítido automáticamente el objetivo adjunto mientras se mueve",
    "Re-space the middle keyframes evenly between the first and last (constant speed)": "Redistribuir uniformemente los fotogramas intermedios entre el primero y el último (velocidad constante)",
    "Recording mode: replace the whole take, or append a new pass after its final keyframe. This does not save the selected frame.": "Modo de grabación: reemplaza toda la toma o añade una nueva pasada después del último fotograma clave. Esto no guarda el fotograma seleccionado.",
    "Rescan replay vehicles, scene actors and nearby entities": "Volver a buscar vehículos de replay, actores de escena y entidades cercanas",
    "Reset camera roll to zero without touching pitch or heading": "Restablecer el alabeo de la cámara sin modificar la inclinación ni la orientación",
    "Reticle and highlight over the entity you are aiming at (with the panel hidden). Turn it off for a clean frame — left-click still attaches.": "Mostrar retícula y resaltado sobre la entidad apuntada con el panel oculto. Desactívalo para un encuadre limpio; el clic izquierdo seguirá adjuntando.",
    "Ride the selected entity while keeping full camera control": "Acompañar a la entidad seleccionada conservando el control total de la cámara",
    "Rigid: the camera orbits and rotates with the target like a hood cam. Off: it rides the target's movement but keeps your framing.": "Rígido: la cámara orbita y rota con el objetivo como una cámara de capó. Desactivado: acompaña su movimiento, pero conserva el encuadre.",
    "Save the current camera position, rotation, FOV and image settings into the selected keyframe": "Guardar la posición, rotación, FOV y ajustes de imagen actuales en el fotograma clave seleccionado",
