(function () {
  const labels = {
    name: ['Set name', 'Nombre del conjunto'], duration: ['Duration (seconds)', 'Duración (segundos)'],
    elements: ['elements', 'elementos'], save: ['Save elements', 'Guardar elementos'],
    place: ['Place and save elements', 'Colocar y guardar elementos'],
    cancel: ['Cancel', 'Cancelar'], edit: ['Edit elements', 'Editar elementos'],
    saved: ['Elements added to the project. Save your project to keep them.', 'Elementos añadidos al proyecto. Guarda el proyecto para conservarlos.'],
    help: ['Place props, peds and vehicles, then save this set. Use your Spooner cursor key to access these controls.',
      'Coloca props, peds y vehículos y guarda el conjunto. Usa la tecla del cursor de Spooner para acceder a estos controles.'],
  };
  for (const [key, values] of Object.entries(labels)) {
    for (const [locale, pack] of Object.entries(window.SD_LANG_PACKS)) pack['spoonerProject.' + key] = values[locale === 'es' ? 1 : 0];
  }
})();

(function () {
  const labels = {
    lights: ['Lights', 'Luces'], addLight: ['Add light', 'Añadir luz'], duplicateLight: ['Duplicate', 'Duplicar'],
    removeLight: ['Remove selected light', 'Eliminar luz seleccionada'],
    confirmRemoveLight: ['Click again to remove', 'Pulsa otra vez para eliminar'],
    saveLights: ['Save lights', 'Guardar luces'],
    pickLightHelp: ['Click a light in the game view or select it here to edit with the gizmo. Save lights keeps each one in its own track or scene entry.',
      'Haz clic en una luz o selecciónala aquí para editarla con el gizmo. Guardar luces conserva cada una en su propia pista o entrada de escena.']
  };
  for (const [key, values] of Object.entries(labels)) {
    for (const [locale, pack] of Object.entries(window.SD_LANG_PACKS)) {
      pack['stageLighting.' + key] = values[locale === 'es' ? 1 : 0];
    }
  }
})();

// My Vehicles has an independent folder library.
(function () {
  const labels = {
    'All vehicles': 'Todos los vehículos',
    'Could not load vehicle folders': 'No se pudieron cargar las carpetas de vehículos',
    'Could not save vehicle folders': 'No se pudieron guardar las carpetas de vehículos',
    'Organize your saved vehicles. Drag vehicles onto a folder or select several to move them together.': 'Organiza tus vehículos guardados. Arrastra vehículos a una carpeta o selecciona varios para moverlos juntos.'
  };
  for (const [key, value] of Object.entries(labels)) {
    window.SD_LANG_PACKS.en.staticText[key] = key;
    window.SD_LANG_PACKS.es.staticText[key] = value;
  }
})();
